using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Linq;using System.Threading;using System.Windows.Forms;
internal sealed class ProgramUpdateButton:ActionButton {public bool UpdateAvailable;protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(UpdateAvailable)using(var fill=new SolidBrush(Color.FromArgb(246,81,81)))e.Graphics.FillEllipse(fill,Width-15,6,7,7);}}
internal sealed partial class Manager {
    bool updatingSoftware,dailyUpdateStarted,checkingSoftwareUpdate;SoftwareRelease availableSoftwareUpdate;
    readonly ProgramUpdateButton updateSoftware=new ProgramUpdateButton();readonly System.Windows.Forms.Timer dailyUpdateTimer=new System.Windows.Forms.Timer{Interval=8000};
    void StartDailyUpdates(){if(dailyUpdateStarted||!companionLive)return;dailyUpdateStarted=true;dailyUpdateTimer.Tick+=delegate{if(busy||checkingStatus||updatingSoftware||petImporting||ImportingWallpapers||downloadingBuiltin||!Enabled||OwnedForms.Length>0||HubPopupMenu.AnyOpen)return;dailyUpdateTimer.Stop();CheckSoftwareUpdate();};dailyUpdateTimer.Start();}
    void SetSoftwareUpdateAvailable(SoftwareRelease release){availableSoftwareUpdate=release;updateSoftware.UpdateAvailable=release!=null;updateSoftware.AccessibleDescription=release==null?"未发现可用更新":"发现新版本 "+release.tag+"，点击下载并更新";updateSoftware.Invalidate();}
    void CheckSoftwareUpdate(){if(checkingSoftwareUpdate||updatingSoftware)return;checkingSoftwareUpdate=true;ImportWork.Start(delegate{try{var release=SoftwareUpdate.FindRelease(GetType().Assembly.GetName().Version);Ui(delegate{SetSoftwareUpdateAvailable(release);if(release!=null)log.Text="发现新版本 "+release.tag+"。点击带红点的更新软件按钮后安装；素材和设置保留。";});}catch(Exception error){Ui(delegate{log.Text="启动更新检查未完成："+error.Message+"；可点击更新软件重试。";});}finally{checkingSoftwareUpdate=false;}});}
    void BuildUpdateButton(){updateSoftware.Text="更新软件";updateSoftware.AccessibleName="更新软件，保留素材与设置";updateSoftware.Click+=delegate{BeginSoftwareUpdate();};commands.Controls.Add(updateSoftware);}
    void BeginSoftwareUpdate(){
        if(PreviewNativeActionBlocked())return;
        if(updatingSoftware||busy)return;if(petImporting||ImportingWallpapers||downloadingBuiltin){log.Text="素材仍在准备，请在完成后更新程序。";return;}updatingSoftware=true;SetBusyControls(true);updateSoftware.Enabled=false;log.Text="正在检查 GitHub 新版本，仅更新程序，保留素材和个人设置…";
        ImportWork.Start(delegate{try{var current=GetType().Assembly.GetName().Version;var release=availableSoftwareUpdate??SoftwareUpdate.FindRelease(current);if(release==null){Ui(delegate{SetSoftwareUpdateAvailable(null);log.Text="未发现可用更新。当前："+Text.Replace("CodexHub · ","")+"（内部版本："+current+"）。";updatingSoftware=false;SetBusyControls(false);updateSoftware.Enabled=true;});return;}string archive=SoftwareUpdate.Download(release,stateDirectory,message=>Ui(delegate{log.Text=message;}));var verified=SoftwareUpdate.VerifyArchive(archive,release.sha256,Path.Combine(stateDirectory,"updates",release.version,"verified-"+Guid.NewGuid().ToString("N")));if(verified.version!=release.version)throw new InvalidDataException("更新包版本与 GitHub 清单不一致。");
            var request=new SoftwareUpdateRequest{Root=root,Archive=archive,Sha256=release.sha256,StateRoot=stateDirectory,ManagerPid=Process.GetCurrentProcess().Id,ManagerStarted=Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks,ResumeArguments=Environment.GetCommandLineArgs().Skip(1).ToArray(),RequestExit=true};string host=SoftwareUpdate.StageHost(root,request);Ui(delegate{LaunchSoftwareUpdate(host);});
        }catch(Exception error){Ui(delegate{log.Text="更新未完成："+error.Message+"\r\n现有程序、素材和设置均未改动。";updatingSoftware=false;SetBusyControls(false);updateSoftware.Enabled=true;});}});
    }
    void LaunchSoftwareUpdate(string host){try{log.Text="校验完成，正在更新程序；完成后自动重新打开。";var started=Process.Start(new ProcessStartInfo(host,"--apply "+SoftwareUpdate.Quote(Path.Combine(Path.GetDirectoryName(host),"request.json"))){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(host)});ThreadPool.QueueUserWorkItem(delegate{using(started){started.WaitForExit();}Ui(delegate{log.Text="更新程序已退出，当前管理器仍在运行。请查看更新窗口的提示后重试。";updatingSoftware=false;SetBusyControls(false);updateSoftware.Enabled=true;});});}catch(Exception error){log.Text="更新未启动："+error.Message;updatingSoftware=false;SetBusyControls(false);updateSoftware.Enabled=true;}}
}